// Golden values of the Deliveries & goods receipt domain (docs/spec/08 §3, 00 §8.8): rows, KPI tiles, status chips,
// drawers and the transitions (Register receipt, Accept → stock, Reject → quarantine) against the prototype's own
// render values (deliveries.golden.json, generated by scripts/proto-golden-deliveries.ts — the prototype logic run in
// node:vm). The prototype's receipts (HLT_DELIV + genDeliv) are rebuilt as `ReceiptLike` rows; deliberate deviations
// are asserted explicitly (dates not zero-padded, inspector = the viewer, the unlisted "Magasin chantier — Lyon").
// Also: what "Announce a delivery" may still bring, the register / QC plans and form parsing, QC routing.
import { describe, expect, it } from 'vitest';
import { parseDateInput } from '@/domain/contract';
import { PROTO, PROTO_GEN } from '@/server/prototype';
import { STATUS_ISO, isoOfDisplayDate, receiptStatus } from '@/server/db/codes';
import {
  DEFAULT_QC_REMARKS, QC_DECIDERS, QC_INBOX_ROLES, RECEIPT_FLOW, canDecideQc, deliveryChips, deliveryKpis, failedOnText, filterReceipts, parseAnnounceForm,
  parseQty, parseRegisterForm, putAwayAfterQc, qcInboxItems, qcPlan, qtyFieldId, qtyText, receiptDrawerView, receiptFilterOf, receiptRowView, registerPlan,
  remainingToAnnounce, type LocationLike, type QcDecision, type ReceiptLike,
} from './deliveries';
import golden from './deliveries.golden.json';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = golden as any;
const PROJECTS = ['HLT-026', 'NDC-031', 'RCF-019', 'ERP-202', 'WSA-044', 'MSR-012', 'EWA-051'];
const LO = 'var(--color-accent-300)';
const TEXT = 'var(--color-text)';
/** Prototype dates are partly zero-padded ("02 Sep"); the rebuild writes "2 Sep" everywhere. */
const day = (s: string) => s.replace(/(^|· )0(\d)/g, '$1$2');
const PART_NAME: Record<string, string> = Object.fromEntries((PROTO.PARTS as { ref: string; name: string }[]).map((p) => [p.ref, p.name]));
const LOCATIONS: LocationLike[] = [
  ...(PROTO.SETTINGS0.locations as [string, string][]).map(([name, label]) => ({ name, type: label, active: true })),
  { name: 'Magasin chantier — Lyon', type: 'Site store', active: false },
].map((l) => ({ ...l, type: l.type.startsWith('Quarantine') ? 'quarantine' : l.type === 'Central warehouse' ? 'central_warehouse' : 'site_store' }));
const loc = (name: string) => LOCATIONS.find((l) => l.name === name)!;
const CENTRAL = loc('Entrepôt central — Lyon');
const QUARANTINE = loc('Zone quarantaine QC — Lyon');

/** The prototype's goods receipts of a project (HLT_DELIV, genDeliv 4449) as database rows; the seed's receiving clerk. */
function protoReceipts(code: string): ReceiptLike[] {
  let raw: any[];
  if (code === 'HLT-026') raw = PROTO.HLT_DELIV;
  else if (!PROTO.DEFS[code]) raw = [];
  else {
    const idx = PROTO.DEFS[code].idx as number;
    const site = code.slice(0, 3) === 'MSR' ? 'Marseille' : 'Lyon';
    raw = (PROTO_GEN.genPOs[code] as any[])
      .filter((o) => o.status === 'Received' || o.status === 'Partially received')
      .map((o, i) => {
        const rec = o.status === 'Received';
        return {
          id: 'BL-2026-0' + (300 + idx * 10 + i), po: o.id, supplier: o.supplier, date: o.expected, carrier: '—', note: o.supplier.slice(0, 2).toUpperCase() + '-' + (4100 + i * 7),
          status: rec ? 'Accepted' : 'QC pending', lines: o.lines.map((l: any) => [l[0], l[1], l[2], rec ? l[2] : 0, 0, 'Magasin chantier — ' + site]),
          qc: rec ? { by: 'Hélène Sauvage', result: 'Passed', remarks: 'Visual + documentary check' } : { by: '—', result: 'Pending', remarks: 'Inspection to schedule' },
          docs: ['Delivery note.pdf'], photos: rec ? 2 : 0,
        };
      });
  }
  const dash = (s: string) => (s === '—' ? null : s);
  return raw.map((d) => ({
    number: d.id, poNumber: d.po, supplier: d.supplier, status: receiptStatus.code(d.status), date: isoOfDisplayDate(d.date), carrier: dash(d.carrier),
    supplierDeliveryNote: dash(d.note), lines: d.lines.map(([ref, o, dq, a, r, l]: any[]) => ({ ref, name: PART_NAME[ref] ?? '', ordered: o, delivered: dq, accepted: a, rejected: r, location: l })),
    qc: { by: dash(d.qc.by), result: dash(d.qc.result), remarks: dash(d.qc.remarks) }, documents: [...d.docs], photoCount: d.photos, receivedBy: 'Fabien Bertrand',
  }));
}

/** Open orders to receive (Ordered or Partially received) of the prototype's orders. */
const openOrders = (code: string) => ((PROTO_GEN.genPOs[code] ?? []) as any[]).filter((o) => o.status === 'Ordered' || o.status === 'Partially received').length;

const kpisOf = (rs: ReceiptLike[], code: string) => deliveryKpis(rs, openOrders(code), 'en').map((k) => ({ label: k.label, value: k.value, sub: k.sub, color: k.lo ? LO : TEXT }));
const rowsOf = (rs: ReceiptLike[]) =>
  rs.map((r) => {
    const v = receiptRowView(r, 'en');
    return {
      id: v.id, po: v.po, supplier: v.supplier, date: v.date, note: v.note, lines: v.lines, qty: v.qty, acc: v.acc, rej: v.rej,
      rejColor: v.rejLo ? LO : 'var(--color-neutral-400)', status: v.statusLabel, tagClass: `tag tag-${v.tone}`, loc: v.loc, qc: v.qc, canReceive: v.canReceive, canQC: v.canQc,
    };
  });
const drawerOf = (r: ReceiptLike) => {
  const d = receiptDrawerView(r, 'en');
  const kv = (xs: typeof d.meta) => xs.map((x) => ({ k: x.k, v: x.v, color: x.lo ? LO : TEXT }));
  return {
    id: d.id, po: d.po, supplier: d.supplier, status: d.statusLabel, tagClass: `tag tag-${d.tone}`, docs: d.docs, noDocs: !d.docs.length, slotId: `deliv-${d.id}`,
    canQC: d.canQc, canReceive: d.canReceive, meta: kv(d.meta), qc: kv(d.qc),
    lines: d.lines.map((l) => ({ ref: l.ref, name: l.name, o: l.o, d: l.d, a: l.a, r: l.r, rColor: l.rLo ? LO : 'var(--color-neutral-500)', loc: l.loc })),
  };
};
/** Golden rows / drawers with the rebuild's date format. */
const gRows = (rows: any[]) => rows.map((r) => ({ ...r, date: day(r.date) }));
const gDrawer = (d: any) => ({ ...d, meta: d.meta.map((m: any) => (m.k === 'Delivered on' ? { ...m, v: day(m.v) } : m)) });
/** Without the selection colour (the screen's view model handles the open row). */
const strip = (rows: any[]) => rows.map((r) => Object.fromEntries(Object.entries(r).filter(([k]) => k !== 'idColor')));

// ── Applying a transition to the prototype rows (what the data-layer writers do) ───────────────────────

function applyRegister(r: ReceiptLike, delivered: Record<string, unknown> = {}, typed: { carrier?: string } = {}): ReceiptLike {
  const p = registerPlan(r.lines, delivered);
  if (!p.ok) throw new Error(p.error);
  return {
    ...r, status: 'qc_pending', date: STATUS_ISO, carrier: typed.carrier ?? r.carrier,
    lines: r.lines.map((l) => ({ ...l, delivered: p.value.delivered[l.ref], accepted: 0, rejected: 0 })),
    qc: { by: null, result: 'Pending', remarks: p.value.remarks },
  };
}

function applyQc(r: ReceiptLike, decision: QcDecision, inspector: string, remarks = ''): ReceiptLike {
  const p = qcPlan(r.lines, decision, remarks);
  if (!p.ok) throw new Error(p.error);
  return {
    ...r, status: p.value.status,
    lines: r.lines.map((l, i) => ({ ...l, accepted: p.value.lines[i].accepted, rejected: p.value.lines[i].rejected, location: putAwayAfterQc(loc(l.location), p.value.lines[i].accepted, CENTRAL, QUARANTINE).name })),
    qc: { by: inspector, result: p.value.result, remarks: p.value.remarks },
  };
}
const replace = (rs: ReceiptLike[], r: ReceiptLike) => rs.map((x) => (x.number === r.number ? r : x));

// ── Seed ───────────────────────────────────────────────────────────────────────────────────────────────

describe('goods receipts of every project (delivRows / delivKpis / delivChips / delivVals)', () => {
  it.each(PROJECTS)('%s', (code) => {
    const rs = protoReceipts(code);
    const g = G.seed.en[code];
    expect(rowsOf(rs)).toEqual(strip(gRows(g.rows)));
    expect(kpisOf(rs, code)).toEqual(g.kpis.map((k: any) => ({ ...k, value: String(k.value) })));
    expect(deliveryChips(rs).map((c) => ({ label: c.label, count: String(c.count) }))).toEqual(g.chips.map((c: any) => ({ label: c.label, count: c.count })));
    for (const r of rs) expect(drawerOf(r)).toEqual(gDrawer(g.drawers[r.number]));
    expect(g.noDeliv).toBe(!rs.length);
  });

  it('Harbor Line: 5 deliveries · 1 announced · 1 awaiting QC · 4 rejected (0.5 %) · 83 % · 4 orders to receive', () => {
    expect(kpisOf(protoReceipts('HLT-026'), 'HLT-026').map((k) => [k.value, k.sub, k.color === LO])).toEqual([
      ['5', '1 announced', false], ['1', 'Held in quarantine', true], ['4', '0.5% of units received', true], ['83%', 'Last 90 days · vs PO expected date', false],
      ['4', 'Ordered or partially received', false],
    ]);
  });

  it('status chips filter the rows (delivFilter); an unknown ?status= falls back to All', () => {
    const rs = protoReceipts('HLT-026');
    for (const [label, ids] of Object.entries(G.filters as Record<string, string[]>))
      expect(filterReceipts(rs, receiptStatus.code(label)).map((r) => r.number)).toEqual(ids);
    expect(RECEIPT_FLOW.map((s) => receiptStatus.label(s))).toEqual(PROTO.DELIV_FLOW);
    expect([receiptFilterOf('qc_pending'), receiptFilterOf('QC pending'), receiptFilterOf('nope'), receiptFilterOf(undefined)]).toEqual(['qc_pending', null, null, null]);
    expect(filterReceipts(rs, null)).toHaveLength(5);
  });

  it('quantities follow the language; the rejected share uses the language decimal separator', () => {
    expect([qtyText(1234, 'en'), qtyText(1234, 'fr').replace(/\s/g, ' ')]).toEqual(['1,234', '1 234']);
    expect(deliveryKpis(protoReceipts('HLT-026'), 4, 'fr')[2].sub).toBe('0,5% of units received');
    expect(deliveryKpis([], 0, 'en')[2]).toEqual({ label: 'Rejected quantity', value: '0', sub: '—', lo: false });
  });
});

// ── Transitions ────────────────────────────────────────────────────────────────────────────────────────

describe('transitions (receive / accept / reject 4455–4456)', () => {
  const hlt = () => protoReceipts('HLT-026');
  const find = (rs: ReceiptLike[], n: string) => rs.find((r) => r.number === n)!;

  it('Register receipt BL-2026-0540: QC pending, delivered = announced, received complete · inspection to do — the inspector is not known yet', () => {
    const g = G.scenarios.register0540.en;
    const rs = replace(hlt(), applyRegister(find(hlt(), 'BL-2026-0540'), {}, { carrier: 'Geodis' }));
    expect(rowsOf(rs)).toEqual(strip(gRows(g.rows)));
    expect(kpisOf(rs, 'HLT-026')).toEqual(g.kpis.map((k: any) => ({ ...k, value: String(k.value) })));
    const d = drawerOf(find(rs, 'BL-2026-0540'));
    // The prototype wrote "Hélène Sauvage" as inspector of every registered receipt (00 §7.16): nobody has inspected yet.
    expect(g.drawer.qc[0].v).toBe('Hélène Sauvage');
    expect(d).toEqual({ ...gDrawer(g.drawer), qc: [{ k: 'Inspector', v: '—', color: TEXT }, ...g.drawer.qc.slice(1)] });
    expect(g.badge).toBe('2');
  });

  it.each([
    ['accept0521', { mode: 'accept' }, 'Gabriel Comte', ''],
    ['accept0521Remarks', { mode: 'accept' }, 'Gabriel Comte', 'Seals intact · routine test report checked'],
    ['reject0521', { mode: 'reject' }, 'Fabien Bertrand', ''],
  ] as [string, QcDecision, string, string][])('%s: lines, location, QC record and KPIs; the viewer is the inspector', (key, decision, who, remarks) => {
    const g = G.scenarios[key].en;
    const rs = replace(hlt(), applyQc(find(hlt(), 'BL-2026-0521'), decision, who, remarks));
    expect(rowsOf(rs)).toEqual(strip(gRows(g.rows)));
    expect(kpisOf(rs, 'HLT-026')).toEqual(g.kpis.map((k: any) => ({ ...k, value: String(k.value) })));
    expect(drawerOf(find(rs, 'BL-2026-0521'))).toEqual(gDrawer(g.drawer));
    expect(g.badge).toBe('');
  });

  it('register then accept BL-2026-0540: stocked at the Le Havre site store', () => {
    const g = G.scenarios.registerAccept0540.en;
    const r = applyQc(applyRegister(find(hlt(), 'BL-2026-0540'), {}, { carrier: 'Geodis' }), { mode: 'accept' }, 'Gabriel Comte');
    const rs = replace(hlt(), r);
    expect(rowsOf(rs)).toEqual(strip(gRows(g.rows)));
    expect(drawerOf(r)).toEqual(gDrawer(g.drawer));
  });

  it('generated receipt of NDC-031: accepted goods put away at the unlisted "Magasin chantier — Lyon" go to the central warehouse; rejected → quarantine', () => {
    const ndc = protoReceipts('NDC-031');
    const id = G.scenarios.acceptNdc.id as string;
    expect(id).toBe('BL-2026-0331');
    const acc = drawerOf(applyQc(find(ndc, id), { mode: 'accept' }, 'Gabriel Comte'));
    const gAcc = gDrawer(G.scenarios.acceptNdc.en.drawer);
    expect(gAcc.lines.map((l: any) => l.loc)).toEqual(['Magasin chantier — Lyon', 'Magasin chantier — Lyon']);
    expect(acc).toEqual({ ...gAcc, lines: gAcc.lines.map((l: any) => ({ ...l, loc: 'Entrepôt central — Lyon' })) });
    const rej = replace(ndc, applyQc(find(ndc, id), { mode: 'reject' }, 'Gabriel Comte'));
    expect(drawerOf(find(rej, id))).toEqual(gDrawer(G.scenarios.rejectNdc.en.drawer));
    expect(kpisOf(rej, 'NDC-031')).toEqual(G.scenarios.rejectNdc.en.kpis.map((k: any) => ({ ...k, value: String(k.value) })));
  });

  it('partial decision (08 OQ9): rejected per article, Partially rejected · "Failed on n units"', () => {
    const r = applyQc(applyRegister(find(hlt(), 'BL-2026-0540')), { mode: 'lines', rejected: { 'FD-SPR-HD': '12' } }, 'Gabriel Comte');
    expect([r.status, r.qc.result, r.qc.remarks, r.lines.map((l) => [l.ref, l.accepted, l.rejected, l.location])]).toEqual([
      'partially_rejected', 'Failed on 12 units', DEFAULT_QC_REMARKS.partially_rejected,
      [['FD-DAMP-FR', 24, 0, 'Magasin chantier — Le Havre'], ['FD-SPR-HD', 408, 12, 'Magasin chantier — Le Havre']],
    ]);
    const all = applyQc(applyRegister(find(hlt(), 'BL-2026-0540')), { mode: 'lines', rejected: { 'FD-DAMP-FR': 24, 'FD-SPR-HD': '420' } }, 'Gabriel Comte');
    expect([all.status, all.qc.result, all.lines.map((l) => l.location)]).toEqual(['rejected', 'Failed', ['Zone quarantaine QC — Lyon', 'Zone quarantaine QC — Lyon']]);
    const none = qcPlan([{ ref: 'A', delivered: 3 }], { mode: 'lines', rejected: {} });
    expect(none.ok && [none.value.status, none.value.result, none.value.remarks]).toEqual(['accepted', 'Passed', 'Conforming — released to stock']);
    expect([failedOnText(1), failedOnText(2)]).toEqual(['Failed on 1 unit', 'Failed on 2 units']);
    const bad = (rejected: Record<string, unknown>) => qcPlan([{ ref: 'A', delivered: 3 }], { mode: 'lines', rejected });
    for (const v of ['4', '-1', '1.5', 'x', 2.5]) expect(bad({ A: v })).toEqual({ ok: false, error: 'Rejected quantities must be whole numbers between 0 and the quantity delivered' });
    expect(bad({ B: '1' })).toEqual({ ok: false, error: 'Unknown article in the decision' });
    const long = qcPlan([{ ref: 'A', delivered: 3 }], { mode: 'accept' }, 'x'.repeat(900));
    expect(long.ok && long.value.remarks.length).toBe(500);
  });
});

// ── My approvals ───────────────────────────────────────────────────────────────────────────────────────

describe('"Delivery — quality check" items (apprItems 4725)', () => {
  it('quality and procurement get the current project\'s QC pending receipts', () => {
    expect(QC_INBOX_ROLES).toEqual(['quality', 'procurement']);
    const items = (code: string) => qcInboxItems(protoReceipts(code)).map(({ id, title, sub, when, who }) => ({ kind: 'Delivery — quality check', id, title, sub, when, who }));
    expect(items('HLT-026')).toEqual(G.inbox.en.quality);
    for (const code of PROJECTS) expect(items(code)).toEqual(G.inbox.en[`procurement:${code}`].map((i: any) => ({ ...i, when: day(i.when) })));
    for (const role of ['director', 'pm', 'depthead', 'member', 'englead', 'client']) expect(G.inbox.en[role]).toEqual([]);
    expect(qcInboxItems(protoReceipts('HLT-026'))[0].whenIso).toBe('2026-09-18');
  });

  it('a decided receipt leaves the queue (the prototype\'s inline call threw; replayed with the delivery handler)', () => {
    const rs = replace(protoReceipts('HLT-026'), applyQc(protoReceipts('HLT-026')[2], { mode: 'accept' }, 'Gabriel Comte'));
    expect(qcInboxItems(rs)).toEqual(G.inbox.en.qualityAfterAccept);
  });

  it('QC decisions: the inbox roles and the portfolio director; the project manager registers but does not accept', () => {
    expect(QC_DECIDERS).toEqual(['quality', 'procurement', 'director']);
    expect((['director', 'pm', 'depthead', 'member', 'englead', 'quality', 'procurement', 'client'] as const).map(canDecideQc)).toEqual([true, false, false, false, false, true, true, false]);
  });
});

// ── Announce a delivery ────────────────────────────────────────────────────────────────────────────────

describe('"Announce a delivery" (announce 4466, SC-4)', () => {
  const poLines = (code: string, po: string) =>
    ((PROTO_GEN.genPOs[code] as any[]).find((o) => o.id === po).lines as [string, number, number][]).map(([ref, ordered, received]) => ({ ref, name: PART_NAME[ref], ordered, received }));
  const receiptsOf = (po: string) => protoReceipts('HLT-026').filter((r) => r.poNumber === po);

  it('Harbor Line: what is still to come per order (the prototype found no order: PO-1078 already has BL-2026-0540)', () => {
    const rem = (po: string) => remainingToAnnounce(poLines('HLT-026', po), receiptsOf(po)).map((l) => [l.ref, l.qty]);
    expect(['PO-1041', 'PO-1052', 'PO-1063', 'PO-1071', 'PO-1078'].map(rem)).toEqual([[], [['EQ-CRN-250T', 2]], [['EL-SWG-11KV', 2]], [['LT-HB-200W', 260]], []]);
    // Once BL-2026-0540 is registered short, the missing sprinkler heads can be announced again.
    const short = applyRegister(receiptsOf('PO-1078')[0], { 'FD-SPR-HD': '400' });
    expect(remainingToAnnounce(poLines('HLT-026', 'PO-1078'), [short]).map((l) => [l.ref, l.qty])).toEqual([['FD-SPR-HD', 20]]);
    // Rejected units are still to come; accepted ones are not.
    const rej = applyQc(short, { mode: 'lines', rejected: { 'FD-DAMP-FR': '4' } }, 'Gabriel Comte');
    expect(remainingToAnnounce(poLines('HLT-026', 'PO-1078'), [rej]).map((l) => [l.ref, l.qty])).toEqual([['FD-DAMP-FR', 4], ['FD-SPR-HD', 20]]);
  });

  it('form: order offered, date in EN / FR / ISO (blank = the order\'s date), carrier, put-away', () => {
    const opts = { orders: ['PO-1052', 'PO-1063'], locations: ['Entrepôt central — Lyon', 'Magasin chantier — Le Havre'], parseDate: (s: string) => parseDateInput(s) };
    expect(parseAnnounceForm({ po: 'PO-1052', expected: '12 oct. 2026', carrier: ' Geodis ', location: 'Magasin chantier — Le Havre' }, opts)).toEqual({
      ok: true, value: { poNumber: 'PO-1052', expectedOn: '2026-10-12', carrier: 'Geodis', location: 'Magasin chantier — Le Havre' },
    });
    expect(parseAnnounceForm({ po: 'PO-1063', expected: '' }, opts)).toEqual({ ok: true, value: { poNumber: 'PO-1063', expectedOn: null, carrier: null, location: null } });
    expect(parseAnnounceForm({ po: 'PO-1078' }, opts)).toEqual({ ok: false, error: 'Choose a purchase order that is waiting for goods' });
    expect(parseAnnounceForm({ po: 'PO-1052', expected: 'soon' }, opts)).toEqual({ ok: false, error: 'Enter a date such as 14 Dec 2026' });
    expect(parseAnnounceForm({ po: 'PO-1052', location: 'Zone quarantaine QC — Lyon' }, opts)).toEqual({ ok: false, error: 'Unknown location' });
  });
});

// ── Register receipt ───────────────────────────────────────────────────────────────────────────────────

describe('"Register receipt" plan and form', () => {
  const lines = [{ ref: 'FD-DAMP-FR', ordered: 24 }, { ref: 'FD-SPR-HD', ordered: 420 }];
  it('delivered: 0 to the quantity announced, at least one unit; complete or incomplete', () => {
    expect(registerPlan(lines)).toEqual({ ok: true, value: { delivered: { 'FD-DAMP-FR': 24, 'FD-SPR-HD': 420 }, complete: true, remarks: 'Received complete · inspection to do' } });
    expect(registerPlan(lines, { 'FD-SPR-HD': '0' })).toEqual({ ok: true, value: { delivered: { 'FD-DAMP-FR': 24, 'FD-SPR-HD': 0 }, complete: false, remarks: 'Received incomplete · inspection to do' } });
    for (const v of ['421', '-1', '2.5', '', 'abc']) expect(registerPlan(lines, { 'FD-SPR-HD': v }).ok).toBe(false);
    expect(registerPlan(lines, { 'FD-DAMP-FR': '0', 'FD-SPR-HD': 0 })).toEqual({ ok: false, error: 'Nothing was delivered' });
    expect(registerPlan([])).toEqual({ ok: false, error: 'Nothing was delivered' });
  });

  it('form: delivered on (EN / FR, default the status date), carrier, delivery note, quantities by field', () => {
    const opts = { today: STATUS_ISO, parseDate: (s: string) => parseDateInput(s) };
    expect(parseRegisterForm({ date: '25 sept. 2026', carrier: 'Geodis', note: ' CF-DN-0921 ', [qtyFieldId('FD-DAMP-FR')]: '24', [qtyFieldId('FD-SPR-HD')]: '420' }, lines, opts)).toEqual({
      ok: true, value: { receivedOn: '2026-09-25', carrier: 'Geodis', supplierDeliveryNote: 'CF-DN-0921', plan: { delivered: { 'FD-DAMP-FR': 24, 'FD-SPR-HD': 420 }, complete: true, remarks: 'Received complete · inspection to do' } },
    });
    expect(parseRegisterForm({}, lines, opts)).toMatchObject({ ok: true, value: { receivedOn: '2026-09-25', carrier: null, supplierDeliveryNote: null } });
    expect(parseRegisterForm({ date: '31 Feb' }, lines, opts)).toEqual({ ok: false, error: 'Enter a date such as 14 Dec 2026' });
    expect(parseRegisterForm({ [qtyFieldId('FD-SPR-HD')]: '500' }, lines, opts)).toEqual({ ok: false, error: 'Delivered quantities must be whole numbers between 0 and the quantity announced' });
    expect([parseQty(' 12 '), parseQty(12), parseQty('1 234'), parseQty('1.5'), parseQty(1.5), parseQty('')]).toEqual([12, 12, 1234, NaN, NaN, NaN]);
  });
});
